@startuml
class InsuranceCompany {
  + CompanyName : string
  + RegistrationNumber : string
}

class PolicyType {
  + TypeName : string
}

class Policy {
  + PolicyId : string
  + CoverageAmount : double
}

class Customer {
  + CustomerId : int
  + Name : string
  + ContactDetails : string
}

class Contract {
  + ContractId : int
  + SigningDate : date
  + Status : string
}

InsuranceCompany "1" -- "*" Policy
Policy "1" -- "*" Contract
Customer "1" -- "*" Contract
@enduml

